        List<FType> xa = ((GenericTypeInstance) a).getTypeParams();
        List<FType> xb = ((GenericTypeInstance) b).getTypeParams();
        if (xa.size() != xb.size()) return false;
        for (int i = 0; i < xa.size(); i++) {
